mapper.select:
SELECT a.LEDGER_ID, a.QUESTION_ID, a.QUESTION_CONTENT FROM inspection.`inspection_question_ledger` a WHERE a.`TASK_ID` = #{params.TASK_ID}
AND a.IS_REPORT = #{params.IS_REPORT}
AND a.QUESTION_ID_2 = #{params.QUESTION_ID_2} AND a.LEDGER_ID IN( SELECT rl.`LEDGER_ID` FROM `inspection`.`inspection_reform_ledger` rl JOIN `inspection`.`inspection_reform_scheme` rs ON rl.`ID` = rs.`REFORM_ID` WHERE rl.`TASK_ID` = #{params.TASK_ID} AND rs.REFORM_SCHEME <> '' AND rs.REFORM_SCHEME IS NOT NULL AND rs.MEMO <> '' AND rs.MEMO IS NOT NULL GROUP BY rl.`LEDGER_ID` ) GROUP BY a.QUESTION_CONTENT ORDER BY a.ADD_DATE

SELECT a.QUESTION_ID_2, a.QUESTION_DSCR_2 FROM inspection.`inspection_question_ledger` a WHERE a.`TASK_ID` = #{params.TASK_ID}
AND a.IS_REPORT = #{params.IS_REPORT}
AND a.QUESTION_ID_1 = #{params.QUESTION_ID_1} AND a.LEDGER_ID IN( SELECT rl.`LEDGER_ID` FROM `inspection`.`inspection_reform_ledger` rl JOIN `inspection`.`inspection_reform_scheme` rs ON rl.`ID` = rs.`REFORM_ID` WHERE rl.`TASK_ID` = #{params.TASK_ID} AND rs.REFORM_SCHEME <> '' AND rs.REFORM_SCHEME IS NOT NULL AND rs.MEMO <> '' AND rs.MEMO IS NOT NULL GROUP BY rl.`LEDGER_ID` ) GROUP BY a.QUESTION_ID_2 ORDER BY a.ADD_DATE

SELECT a.QUESTION_ID_1, a.QUESTION_DSCR_1 FROM inspection.`inspection_question_ledger` a WHERE a.`TASK_ID` = #{params.TASK_ID}
AND a.IS_REPORT = #{params.IS_REPORT}
AND a.LEDGER_ID IN( SELECT rl.`LEDGER_ID` FROM `inspection`.`inspection_reform_ledger` rl JOIN `inspection`.`inspection_reform_scheme` rs ON rl.`ID` = rs.`REFORM_ID` WHERE rl.`TASK_ID` = #{params.TASK_ID} AND rs.REFORM_SCHEME <> '' AND rs.REFORM_SCHEME IS NOT NULL AND rs.MEMO <> '' AND rs.MEMO IS NOT NULL GROUP BY rl.`LEDGER_ID` ) GROUP BY a.QUESTION_ID_1 ORDER BY a.ADD_DATE

SELECT a.id, a.CONTENT_DSCR, a.CONTENT_PID, a.SORT FROM
inspection.`inspection_content` a
inspection.`inspection_content_regbook` a
WHERE
a.`TYPE_CODE` = #{params.TYPE_CODE}
a.`BOOK_ID` = #{params.BOOK_ID}
AND a.`CONTENT_PID` = #{params.CONTENT_PID}

SELECT *
FROM `inspection`.`inspection_register_book` a
WHERE 1=1

    AND a.TASK_ID = #{params.TASK_ID}


    AND a.BOOK_ID = #{params.BOOK_ID}
